interface GradeStageDraft { min: string; label: string; shortLabel: string; icon: CreatorGradeIcon }
const gradeIconLabels: Record<CreatorGradeIcon, string> = { SPARKLES: '새싹 · 반짝임', AWARD: '가이드 · 메달', STAR: '큐레이터 · 별', ROUTE: '루트 메이커 · 경로', CROWN: '마스터 · 왕관' };
